// Turns the KPI row into a short Arabic email for the production manager (right-to-left).
// The numbers come from the kpi_last_7_days view; nothing here is written by the AI.
const k = $input.first().json;
const upcoming = k.upcoming || [];
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
// Dates like 2026-10-21 are kept left-to-right, or Arabic text around them flips their parts.
const cell = s => esc(s).replace(/\d{4}-\d{2}-\d{2}/g, d => `<span dir="ltr">${d}</span>`);
const num = v => (v === null || v === undefined ? '-' : String(v));
const minutes = v => {
  if (v === null || v === undefined) return '-';
  const m = Number(v);
  return m < 60 ? `${m.toFixed(1)} دقيقة` : `${(m / 60).toFixed(1)} ساعة`;
};

// One line per KPI: label, value, and a short explanation in plain Arabic.
const tiles = [
  ['طلبات الحجز', num(k.booking_requests), `عدد الرسائل التي وصلت لصندوق الحجوزات: ${num(k.emails_handled)}`],
  ['نسبة الطلبات الكاملة', k.auto_routed_pct === null ? '-' : `${k.auto_routed_pct}%`, 'وصلت للمدير مباشرة دون الحاجة لأسئلة إضافية'],
  ['تحتاج معلومات', num(k.needs_info), 'تم تجهيز رد للموظف ليرسله'],
  ['نسبة الموافقة', k.approval_rate_pct === null ? '-' : `${k.approval_rate_pct}%`, `موافقة: ${num(k.approved)}، رفض: ${num(k.rejected)}، انتهت مهلتها: ${num(k.expired)}. الروابط غير الصالحة لا تُحسب (${num(k.invalid_clicks)})`],
  ['متوسط وقت القرار', minutes(k.avg_minutes_to_decision), `الوسيط ${minutes(k.median_minutes_to_decision)}، من وصول الرسالة حتى ضغط المدير`],
  ['تعارضات تم التنبيه لها', num(k.clashes_flagged), 'نفس الاستوديو أو المعدة في تواريخ متداخلة'],
  ['بانتظار قرارك', num(k.waiting_for_manager), 'طلبات أُرسلت ولم يتم الضغط عليها بعد'],
  ['حجوزات أُلغيت', num(k.cancelled), 'أُلغيت بعد الموافقة، ولم تعد تُحسب في فحص التعارض'],
  ['تكلفة الذكاء الاصطناعي', `$${Number(k.ai_cost_usd || 0).toFixed(4)}`, `عدد الاستدعاءات: ${num(k.ai_calls)}، حوالي $${Number(k.ai_cost_per_booking_usd || 0).toFixed(4)} لكل حجز`],
  ['الوقت الموفَّر (تقدير)', minutes(k.est_minutes_saved), `على افتراض ${num(k.minutes_per_request)} دقائق يدوية لكل طلب كامل`],
  ['أخطاء النظام', num(k.errors), 'مسجلة في جدول الأخطاء للمراجعة'],
];

const upcomingRows = upcoming.length
  ? upcoming.map(u => `<tr><td style="padding:6px;border-bottom:1px solid #eee"><bdi>${esc(u.resource || u.item)}</bdi></td><td style="padding:6px;border-bottom:1px solid #eee"><bdi>${esc(u.production)}</bdi></td><td style="padding:6px;border-bottom:1px solid #eee">${cell(u.start_date)} إلى ${cell(u.end_date)}</td><td style="padding:6px;border-bottom:1px solid #eee">${esc(u.quantity)}</td></tr>`).join('\n')
  : '<tr><td colspan="4" style="padding:6px">لا توجد حجوزات معتمدة في الأسبوعين القادمين.</td></tr>';

// "label: number" everywhere avoids Arabic number-noun agreement ("8 طلب" is wrong Arabic).
const subject = `ملخص الحجوزات الأسبوعي: عدد الطلبات ${num(k.booking_requests)}، الحجوزات المعتمدة ${num(k.approved)}`;
const html = `<!doctype html>
<html lang="ar" dir="rtl"><body style="margin:0;background:#f4f1ea">
<div dir="rtl" style="max-width:680px;margin:0 auto;padding:24px;font-family:Tahoma,Arial,sans-serif;text-align:right;color:#222">
  <h2 style="margin:0 0 4px;color:#5a3e1b">ملخص الحجوزات - آخر 7 أيام</h2>
  <p style="margin:0 0 16px;color:#666">من نظام حجوزات الاستوديوهات والمعدات. الأرقام محسوبة من قاعدة البيانات مباشرة.</p>
  <table style="width:100%;border-collapse:collapse;background:#fff">
    ${tiles.map(([label, value, hint]) => `<tr><th style="text-align:right;padding:10px;border-bottom:1px solid #eee;width:34%">${esc(label)}</th><td style="padding:10px;border-bottom:1px solid #eee;font-size:20px;font-weight:bold;color:#5a3e1b;width:22%"><bdi>${esc(value)}</bdi></td><td style="padding:10px;border-bottom:1px solid #eee;color:#666;font-size:13px">${esc(hint)}</td></tr>`).join('\n    ')}
  </table>
  <h3 style="margin:24px 0 8px;color:#5a3e1b">الحجوزات المعتمدة في الأسبوعين القادمين</h3>
  <table style="width:100%;border-collapse:collapse;background:#fff">
    <tr style="background:#efe7d8"><th style="text-align:right;padding:6px">المعدة / الاستوديو</th><th style="text-align:right;padding:6px">الإنتاج</th><th style="text-align:right;padding:6px">التواريخ</th><th style="text-align:right;padding:6px">العدد</th></tr>
    ${upcomingRows}
  </table>
  <p style="margin-top:24px;color:#666;font-size:13px">"الوقت الموفَّر" تقدير مبني على افتراض قابل للتعديل في جدول الإعدادات، وليس قياساً. بيانات العرض تجريبية.</p>
</div></body></html>`;

const text = [
  'ملخص الحجوزات - آخر 7 أيام', '',
  ...tiles.map(([label, value, hint]) => `${label}: ${value} (${hint})`), '',
  'الحجوزات المعتمدة في الأسبوعين القادمين:',
  ...(upcoming.length ? upcoming.map(u => `- ${u.resource || u.item} | ${u.production} | ${u.start_date} إلى ${u.end_date} | ${u.quantity}`) : ['لا توجد.']),
].join('\n');

// The KPI numbers without the upcoming list, for report_log.
const { upcoming: _drop, ...kpis } = k;
return [{ json: { subject, text, html, kpis } }];
